class Solution {
    public String maskPII(String s){
        if(s.indexOf('@')>=0){
            String lower=s.toLowerCase();
            int at=lower.indexOf('@');
            return lower.charAt(0)+"*****"+lower.charAt(at-1)+lower.substring(at);
        }
        String digits=s.replaceAll("\\D","");
        int country=digits.length()-10;
        StringBuilder answer=new StringBuilder();
        if(country>0)answer.append('+').append("*".repeat(country)).append('-');
        answer.append("***-***-").append(digits.substring(digits.length()-4));
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun maskPII(s:String):String{
        if('@' in s){
            val lower=s.lowercase();
            val at=lower.indexOf('@');
            return "${lower[0]}*****${lower[at-1]}${lower.substring(at)}"
        };
        val digits=s.filter{
            it.isDigit()
        };
        val country=digits.length-10;
        return(if(country>0)"+"+"*".repeat(country)+"-" else "")+"***-***-"+digits.takeLast(4)
    }
}

